import{Bt as e,St as t,Ut as n,at as r,it as i,ot as a,st as o,tt as s,vt as c}from"./chunks/framework.dmHZ7NHG.js";import{n as l}from"./chunks/theme.C_Cnft65.js";var u={id:`trials`,tabindex:`-1`},d={class:`rcpt-big`},f={tabindex:`0`},p=JSON.parse(`{"title":"Trials","description":"How the uuidna trial works — every theorem folded order-invariant to one recomputable receipt, and ONE answer for any statement, VERIFIED or UNVERIFIED, all else void. uuidna verifies; it never refutes. It can fail (a note that cites a proof not in the ledger), and a receipt recomputes the rest.","frontmatter":{"title":"Trials","description":"How the uuidna trial works — every theorem folded order-invariant to one recomputable receipt, and ONE answer for any statement, VERIFIED or UNVERIFIED, all else void. uuidna verifies; it never refutes. It can fail (a note that cites a proof not in the ledger), and a receipt recomputes the rest.","aside":false},"headers":[],"relativePath":"docs/trials.md","filePath":"docs/trials.md"}`),m=Object.assign({name:`docs/trials.md`},{setup(p){return(p,m)=>{let h=t(`Badge`),g=t(`Handle`),_=t(`FoldAnimation`);return c(),i(`div`,null,[s(`h1`,u,[m[0]||=a(`Trials `,-1),o(h,{type:`tip`,text:`${e(l).total} theorems`},null,8,[`text`]),m[1]||=a(),m[2]||=s(`a`,{class:`header-anchor`,href:`#trials`,"aria-label":`Permalink to “Trials”`},`​`,-1)]),m[9]||=r(`<blockquote><p>A claim is not trusted, it is tried — and the verdict recomputes.</p></blockquote><p>A <strong>trial</strong> is a recomputable verdict. It does not ask you to believe anything; it hands back a result anyone can recheck. Run one for a single statement with <code>uuidna_trial</code>, or fold the whole ledger through it — below.</p><h2 id="the-live-receipt" tabindex="-1">The live receipt <a class="header-anchor" href="#the-live-receipt" aria-label="Permalink to “The live receipt”">​</a></h2><p>Every theorem&#39;s content-address, folded <strong>order-invariant</strong> to <strong>one</strong> recomputable receipt. Change one theorem — or one bit of one proof — and the receipt moves. Recompute it yourself from this same tree with <code>npm run lean</code>.</p>`,4),s(`p`,d,[o(g,{uuid:e(l).trial.receipt},null,8,[`uuid`])]),o(_,{receipt:e(l).trial.receipt},null,8,[`receipt`]),s(`table`,f,[m[8]||=s(`thead`,null,[s(`tr`,null,[s(`th`,null,`field`),s(`th`,null,`value`)])],-1),s(`tbody`,null,[s(`tr`,null,[m[3]||=s(`td`,null,`theorems folded`,-1),s(`td`,null,n(e(l).trial.count),1)]),s(`tr`,null,[m[4]||=s(`td`,null,`verified (proven in Lean)`,-1),s(`td`,null,n(e(l).trial.verified),1)]),s(`tr`,null,[m[5]||=s(`td`,null,`lean-backed`,-1),s(`td`,null,n(e(l).trial.leanBacked),1)]),s(`tr`,null,[m[6]||=s(`td`,null,`order-invariant`,-1),s(`td`,null,n(e(l).trial.orderInvariant?`yes — any pairing folds to the same root`:`no`),1)]),s(`tr`,null,[m[7]||=s(`td`,null,`sequential chain tip`,-1),s(`td`,null,[s(`code`,null,n(e(l).trial.chainTip),1)])])])]),m[10]||=r(`<p>The fold folds every direction at once — forward, reverse, any pairing — and lands on the same root: that is the order-invariance the animation shows. The <strong>chain tip</strong> is the other reading: the same addresses folded <em>sequentially</em>, each link&#39;s receipt seeding the next (the referer ratchet). Two honest views of the same sealed set.</p><h2 id="the-one-answer-—-verified-or-unverified-all-else-void" tabindex="-1">The one answer — VERIFIED or UNVERIFIED, all else void <a class="header-anchor" href="#the-one-answer-—-verified-or-unverified-all-else-void" aria-label="Permalink to “The one answer — VERIFIED or UNVERIFIED, all else void”">​</a></h2><p>A trial on a single statement returns <strong>one</strong> answer, and only one of <strong>two</strong> — as a function of the statement, not an opinion:</p><table tabindex="0"><thead><tr><th>verdict</th><th>when</th><th>meaning</th></tr></thead><tbody><tr><td><strong>VERIFIED</strong></td><td>a decidable test recomputes true, <strong>or</strong> it cites a sealed Lean theorem</td><td>a <code>by decide</code> proof backs it — settled, recomputable by anyone</td></tr><tr><td><strong>UNVERIFIED</strong></td><td>everything else</td><td>no test, no sealed citation, a failed test, or a citation to a proof that is <strong>not</strong> in the ledger — which verifies nothing. <strong>Not &quot;false&quot;</strong> — just not verified</td></tr></tbody></table><p><strong>uuidna verifies; it never refutes.</strong> Calling a claim <em>false</em> is an overclaim it cannot decide — absence of proof is not proof of falsity — so there is no third verdict. The receipt is a content-address, so two people running the same trial on the same statement get the same answer.</p><h2 id="the-charter-—-what-the-trial-does-and-does-not-judge" tabindex="-1">The charter — what the trial does and does not judge <a class="header-anchor" href="#the-charter-—-what-the-trial-does-and-does-not-judge" aria-label="Permalink to “The charter — what the trial does and does not judge”">​</a></h2><p>A public trial carries credibility only if its stance is stated plainly. This is the whole of it, drawn from the two answers above — no more, no less:</p><ul><li><strong>The claim is on trial, never the person, never the idea&#39;s worth.</strong> A trial judges <em>integrity</em> — does a statement earn what it asserts — not merit, taste, or who wrote it. There is no verdict for &quot;unwelcome&quot; and none for &quot;brilliant&quot;.</li><li><strong>Every idea is heard, and none is called false.</strong> Any statement can be tried. An idea without a proof is <strong>UNVERIFIED</strong> — held open, never dismissed, never labelled false — and it leaves with an ordered <code>develop</code> plan: name the finite structure, write the boolean predicate, supply it. An idea is <em>not</em> left at &quot;UNVERIFIED, good luck&quot;.</li><li><strong>The only distinction is a proof.</strong> <strong>VERIFIED</strong> happens only when a recomputable test holds or a sealed theorem backs it. Respect for an idea is not agreement with it: the trial reports whether a proof stands, not whether the reader likes it.</li><li><strong>Nothing is refused — one thing is not shipped.</strong> The trial refuses no idea. The <em>publish</em> gate does refuse one thing: shipping a note that cites a proof which does not exist in the ledger (a fabricated citation). That is a quality check on the making, not a verdict that the idea is false — the remedy is <em>&quot;seal that theorem, or drop the citation and bring a test&quot;</em>.</li><li><strong>Public and equal.</strong> Every answer is content-addressed and recomputable by anyone, and the fold is order-invariant: the same receipt for every observer, whatever order they read in. No private verdict, no privileged reader.</li></ul><p><strong>The honest limit — credibility <em>is</em> responsibility.</strong> &quot;Every idea heard&quot; is not &quot;every claim verified&quot;. Leaving an unbacked claim UNVERIFIED is not judging the idea — it is holding the <em>claim</em> to what it earns; drop that and a VERIFIED would mean nothing. The trial expects nothing of an idea except that it not claim a proof it does not have.</p><h2 id="it-can-fail" tabindex="-1">It can fail <a class="header-anchor" href="#it-can-fail" aria-label="Permalink to “It can fail”">​</a></h2><p>The trial is <strong>not rigged to pass</strong>. The publish gate exits non-zero when a note cites a proof that is not in the ledger — the opposite of a rubber stamp. A build that ships a fabricated citation <strong>fails the audit</strong>. That a trial <em>can</em> fail is what makes a VERIFIED mean anything.</p><h2 id="it-hardens-in-real-life" tabindex="-1">It hardens in real life <a class="header-anchor" href="#it-hardens-in-real-life" aria-label="Permalink to “It hardens in real life”">​</a></h2><p>The gate is not frozen. Every real near-miss sharpens it: a false &quot;pass&quot; becomes a new rule; a false &quot;fail&quot; (a citation mistaken for a claim, a debunk mistaken for the thing it debunks) becomes a new demarcation — fixed at the root, not patched at the surface, so the same class of mistake cannot recur. The gate audits README, every docs page, all MCP descriptions, every theorem &quot;why&quot;, the Lean headers, and the source comments.</p><h2 id="what-a-trial-is-not" tabindex="-1">What a trial is not <a class="header-anchor" href="#what-a-trial-is-not" aria-label="Permalink to “What a trial is not”">​</a></h2><ul><li><strong>Not a truth oracle.</strong> A content-address proves <strong>integrity</strong> — that nothing was quietly changed — not that a claim is <em>true</em>. The trial tells you a statement is honest and recomputable, or that it overclaims; never that the world agrees.</li><li><strong>Not a judgement of people.</strong> A trial adjudicates a <strong>statement</strong>, and its remedy is paid in code (link a sealed theorem, or demarcate the claim), never in blame.</li><li><strong>Not a manipulation-proof filter — and honest about it.</strong> The honesty gate is a <strong>hardcoded, incomplete word lexicon</strong> — the <em>one</em> place uuidna hardcodes, and so its weakest, most compromised part. It is a <strong>heuristic floor</strong> that catches careless overclaims (it caught many while this project was built), not a wall against a determined one: synonyms, cross-script homoglyphs and paraphrase evade it <em>by construction</em>, because &quot;is this sentence dishonest?&quot; is not decidable arithmetic and cannot compute from the sequence. uuidna&#39;s integrity does <strong>not</strong> rest on the gate. It rests on the <strong>recomputable proofs and receipts</strong> — which <em>are</em> computed, complete over their domain, and recheckable by anyone. <strong>Trust the recomputation, not the word-list.</strong></li></ul><p>The theorems are on <a href="/theorems">Theorems</a> (by principle) and <a href="/topics">Topics</a> (by skill); the <a href="/tests">Tests</a> and the tools on <a href="/mcp">MCP</a> are the other readings of the same discipline. A theorem computes in Lean, or it is not a theorem — and the receipt is the proof that nothing here was quietly changed. Integrity, not truth.</p>`,16)])}}});export{p as __pageData,m as default};